    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x, grid[y][x]))
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != bg and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            minr = min(y for y, x, v in cells)
            maxr = max(y for y, x, v in cells)
            minc = min(x for y, x, v in cells)
