def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))

    boxes = []
    for r in range(h - 4):
        for c in range(w - 4):
            frame = grid[r][c]
            if frame not in (2, 8):
                continue
            inner = grid[r + 1][c + 1]
            if inner == frame:
                continue
            if any(grid[r][x] != frame or grid[r + 4][x] != frame
                   for x in range(c, c + 5)):
                continue
            if any(grid[y][c] != frame or grid[y][c + 4] != frame
                   for y in range(r, r + 5)):
                continue
            if any(grid[y][x] != inner
                   for y in range(r + 1, r + 4)
                   for x in range(c + 1, c + 4)):
                continue
            boxes.append([r, c, frame, inner])

    # Slide same-direction boxes toward their respective edge, with boxes
    # encountered earlier acting as blockers.
    placed = []
    for frame, order in ((8, "left"), (2, "right")):
        group = [b for b in boxes if b[2] == frame]
        group.sort(key=lambda b: b[1], reverse=(order == "right"))
        for b in group:
            r, c, _, _ = b
            if order == "left":
                while c > 0:
                    nc = c - 1
                    if any(max(r, pr) < min(r + 5, pr + 5) and
                           max(nc, pc) < min(nc + 5, pc + 5)
                           for pr, pc, pf in placed if pf == frame):
                        break
                    c = nc
            else:
                while c + 5 < w:
                    nc = c + 1
                    if any(max(r, pr) < min(r + 5, pr + 5) and
                           max(nc, pc) < min(nc + 5, pc + 5)
                           for pr, pc, pf in placed if pf == frame):
                        break
                    c = nc
            b[1] = c
            placed.append((r, c, frame))

    out = [[bg] * w for _ in range(h)]
    for r, c, frame, inner in boxes:
        for y in range(5):
            for x in range(5):
                out[r + y][c + x] = (
                    inner if 1 <= y <= 3 and 1 <= x <= 3 else frame
                )
    return out
